import { execFile } from "node:child_process";
import { readFile } from "node:fs/promises";
import { promisify } from "node:util";
import { expect, test } from "vitest";
import { crawlerApiDocument } from "../server/modules/ingest/routes.ts";

// Generated files are regenerated by their commands, and have to be up to date.

test("the database types match the migrations", async () => {
  // This file's database, which the migrations made.
  await promisify(execFile)("node_modules/.bin/kysely-codegen", ["--verify"]);
});

test("the crawler's OpenAPI document matches its routes", async () => {
  expect(crawlerApiDocument()).toBe(await readFile("openapi/crawler.json", "utf8"));
});

// Seeding goes through the ingest services, so this catches it falling behind them.
test("seeding an empty database works", { timeout: 30_000 }, async () => {
  await promisify(execFile)("node", ["scripts/seed.ts"]);
});
